CAM = {'shet': [700, 590, 1.6], 'north': [820, 310, 1.6], 'gap': [480, 460, 1.6], 'nsea': [710, 670, 1.6]}


_TH = json.load(open(__import__('os').path.dirname(__import__('os').path.abspath(__file__)) + '/th/theatres.json', encoding='utf-8'))
for _k, _v in _TH.items():
    if _k.startswith('__'): continue
    for _s, _i in _v['scinfo'].items():
        ZONE[_s] = _i['zone']; CAM[_s] = _i['cam']; A_[_s] = _i['assets']

def patrol(key, sector_or_zone, need, fail=None):
    z = ZONE[sector_or_zone] if isinstance(sector_or_zone, str) else sector_or_zone
    o = {'k': 'patrol', 'key': key, 'zone': z, 'need': need}
    if fail: o['onFail'] = [fail]
    return o
def close(key, c, n=1, fail=1, on=None):
    o = {'k': 'close', 'key': key, 'c': c}
    if n != 1: o['n'] = n
    if fail != 1: o['fail'] = fail
    if on: o['onFail'] = [on]
    return o
HOLD = {'k': 'hold', 'key': 'ob.hold'}
ESC = {'k': 'escort', 'key': 'ob.escort'}

def sc(id, sector, mode, diff, tags, title, desc, brief, rec, hyp, phases, script, pool, sec=('noFalse', 'cs55', 'noLoss'), **kw):
    loc = mode == 'local'
    d = dict(id=id, sector=sector, mode=mode, diff=diff, tags=tags, title=dict(fr=title[0], en=title[1]), desc=dict(fr=desc[0], en=desc[1]), brief=dict(fr=brief[0], en=brief[1]),
             turns=phases[-1]['until'], budget=40 if loc else 62, rec=rec, hyp=hyp, assets=A_[sector if loc else kw.pop('area', 'all')], maxA=2 if loc else 3, dyn=.25 if loc else .3, sec=list(sec), pool=pool, phases=phases, script=script)
    if loc: d['cam'] = CAM[sector]
    d.update(kw)
    return d
def P3(a, b, c, t=(3, 6, 10), ks=None, convoy=None):
    out = []
    for i, (u, o) in enumerate(zip(t, (a, b, c))):
        p = {'until': u, 'obj': o}
        if ks: p['k'] = ks[i]
        if convoy and i == 1: p['convoy'] = convoy
        out.append(p)
    return out
