for x in S:
    if x.get('tuto') or x.get('req'): continue
    if 'mer' in x['tags'] and x['id'][0] != 'c': x['pool'].setdefault('mine', 1)
    if 'sous-marin' in x['tags']: x['pool'].setdefault('seabed', 1)
    if x['mode'] == 'intl' and x['diff'] >= 2 and x['id'][0] != 'c': x['pool'].setdefault('evac', 1)
for x in S:
    if x.pop('diff4', None): x['diff'] = 3
# missions plus longues : le découpage en phases, le script et les présences requises suivent
LONG = 1.6
for x in S:
    if x.get('tuto'): continue
    for p in x['phases']:
        p['until'] = round(p['until'] * LONG)
        for o in p['obj']:
            if o.get('k') == 'patrol' and o.get('need'): o['need'] = round(o['need'] * LONG)
    x['turns'] = x['phases'][-1]['until']
    x['script'] = [[max(1, round(e[0] * LONG))] + list(e[1:]) for e in x['script']]

